+func formatDuration(d time.Duration) string {
+	if d < 0 {
+		d = 0
+	}
+	if d == 0 {
+		return "0ns"
+	}
+
+	type unit struct {
+		size time.Duration
+		name string
+	}
+	units := []unit{
+		{24 * time.Hour, "d"},
+		{time.Hour, "h"},
+		{time.Minute, "m"},
+		{time.Second, "s"},
+		{time.Millisecond, "ms"},
+		{time.Microsecond, "us"},
+		{time.Nanosecond, "ns"},
+	}
+
+	parts := make([]string, 0, 4)
+	for _, unit := range units {
+		if d < unit.size {
+			continue
+		}
+		value := d / unit.size
+		d -= value * unit.size
+		parts = append(parts, strconv.FormatInt(int64(value), 10)+unit.name)
+	}
+	if len(parts) == 0 {
+		return "0ns"
+	}
+	return strings.Join(parts, " ")
+}
