	helpText       = `Find the password of protected ZIP files

Usage: executable [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
`
)

var (
	defaultCharsetSpec = "lud"
	optionDisplays     = map[string]string{
		"inputFile":          "--inputFile <inputFile>",
		"workers":            "--workers <workers>",
		"passwordDictionary": "--passwordDictionary <passwordDictionary>",
		"charset":            "--charset <charset>",
		"charsetFile":        "--charsetFile <charsetFile>",
		"minPasswordLen":     "--minPasswordLen <minPasswordLen>",
		"maxPasswordLen":     "--maxPasswordLen <maxPasswordLen>",
		"fileNumber":         "--fileNumber <fileNumber>",
		"startingPassword":   "--startingPassword <startingPassword>",
	}
	charsetClasses = map[byte][]byte{
		'l': []byte("abcdefghijklmnopqrstuvwxyz"),
		'u': []byte("ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
		'd': []byte("0123456789"),
		'h': []byte("0123456789abcdef"),
		'H': []byte("0123456789ABCDEF"),
		's': []byte(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"),
	}
)

type cliMode int

const (
	cliModeRun cliMode = iota
	cliModeHelp
	cliModeVersion
)

type cliError struct {
	exitCode int
	message  string
}

type config struct {
	inputFile          string
	workers            int
	passwordDictionary string
	charsetSpec        string
	charsetFile        string
	minPasswordLen     int
	maxPasswordLen     int
	fileNumber         int
	startingPassword   string
}

type runConfig struct {
	cfg     config
	dict    [][]byte
	charset []byte
}

func main() {
	cfg, mode, err := parseArgs(os.Args[1:])
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	switch mode {
	case cliModeHelp:
		writeStdout(helpText)
		return
	case cliModeVersion:
		writeStdout(appVersion + "\n")
		return
	}

	runCfg, err := validateRunConfig(cfg)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	target, err := loadEncryptedTarget(runCfg.cfg.inputFile, runCfg.cfg.fileNumber)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	tty := isTTY(os.Stdout)
	if tty {
		printTTYPrelude(target, runCfg)
	}

	start := time.Now()
	var found bool
	var password []byte
	if len(runCfg.dict) > 0 {
		found, password = searchDictionary(target, runCfg.dict, runCfg.cfg.workers)
	} else {
		found, password = searchBruteForce(
