			runCfg.charset,
			runCfg.cfg.minPasswordLen,
			runCfg.cfg.maxPasswordLen,
			[]byte(runCfg.cfg.startingPassword),
			runCfg.cfg.workers,
		)
	}

	writeStdout("Time elapsed: " + formatDuration(time.Since(start)) + "\n")
	if found {
		writeStdout("Password found:" + string(password) + "\n")
		return
	}
	writeStdout("Password not found\n")
}

