					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'p')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					if cliErr := markSeen(seen, &seenOrder, "passwordDictionary"); cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
					cfg.passwordDictionary = v
				case 'c':
					v, cliErr := shortOptionValue(args, &i, cluster, &j, 'c')
					if cliErr != nil {
						return cfg, cliModeRun, cliErr
					}
