func validateRunConfig(cfg config) (runConfig, *cliError) {
	if !pathExists(cfg.inputFile) {
		return runConfig{}, runtimeArgError("'inputFile' does not exist")
	}
	if cfg.passwordDictionary != "" && !pathExists(cfg.passwordDictionary) {
		return runConfig{}, runtimeArgError("'passwordDictionary' does not exist")
	}
	if cfg.charsetFile != "" && !pathExists(cfg.charsetFile) {
		return runConfig{}, runtimeArgError("'charsetFile' does not exist")
	}
	if cfg.workers <= 0 {
		return runConfig{}, runtimeArgError("'workers' must be positive")
	}
	if cfg.maxPasswordLen < cfg.minPasswordLen {
		return runConfig{}, runtimeArgError("'maxPasswordLen' must be equal or greater than 'minPasswordLen'")
	}
	if cfg.passwordDictionary != "" && cfg.startingPassword != "" {
		return runConfig{}, runtimeArgError("'startingPassword' cannot be used with a dictionary file")
	}

	runCfg := runConfig{cfg: cfg}
	if cfg.passwordDictionary != "" {
		dict, err := loadDictionary(cfg.passwordDictionary)
		if err != nil {
			return runConfig{}, err
		}
		runCfg.dict = dict
		return runCfg, nil
	}

	var charset []byte
	var err *cliError
	if cfg.charsetFile != "" {
		charset, err = loadCharsetFile(cfg.charsetFile)
	} else {
		charset, err = buildCharsetFromSpec(cfg.charsetSpec)
	}
	if err != nil {
		return runConfig{}, err
	}

	if cfg.startingPassword != "" {
		passwordBytes := []byte(cfg.startingPassword)
		if len(passwordBytes) < cfg.minPasswordLen || len(passwordBytes) > cfg.maxPasswordLen {
			return runConfig{}, runtimeArgError("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration")
		}
		if !charsetContainsAll(charset, passwordBytes) {
			return runConfig{}, runtimeArgError("'startingPassword' uses characters out of the generation charset")
		}
	}

	runCfg.charset = charset
	return runCfg, nil
}

func loadDictionary(path string) ([][]byte, *cliError) {
	file, err := os.Open(path)
	if err != nil {
		return nil, runtimeArgError("'passwordDictionary' does not exist")
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	passwords := make([][]byte, 0)
	for scanner.Scan() {
		line := append([]byte(nil), scanner.Bytes()...)
		passwords = append(passwords, line)
	}
	if err := scanner.Err(); err != nil {
		return nil, &cliError{exitCode: 1, message: "Dictionary file error - " + err.Error() + "\n"}
	}
	return passwords, nil
}

func loadCharsetFile(path string) ([]byte, *cliError) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, runtimeArgError("'charsetFile' does not exist")
	}
	return uniqueSortedBytes(data), nil
}

func buildCharsetFromSpec(spec string) ([]byte, *cliError) {
	set := make([]byte, 0, 64)
	for i := 0; i < len(spec); i++ {
		chars, ok := charsetClasses[spec[i]]
		if !ok {
			return nil, runtimeQuotedError(fmt.Sprintf("Unknown charset option '%c'", spec[i]))
		}
		set = append(set, chars...)
	}
	return uniqueSortedBytes(set), nil
}

func charsetContainsAll(charset, value []byte) bool {
	if len(value) == 0 {
		return true
	}
	var table [256]bool
	for _, b := range charset {
		table[b] = true
	}
	for _, b := range value {
		if !table[b] {
			return false
		}
	}
	return true
}

func uniqueSortedBytes(src []byte) []byte {
	if len(src) == 0 {
		return nil
	}
	seen := [256]bool{}
	dst := make([]byte, 0, len(src))
	for _, b := range src {
		if !seen[b] {
			seen[b] = true
			dst = append(dst, b)
		}
	}
	sort.Slice(dst, func(i, j int) bool { return dst[i] < dst[j] })
	return dst
}

func searchDictionary(target *encryptedTarget, dict [][]byte, workers int) (bool, []byte) {
	if len(dict) == 0 {
		return false, nil
	}

	var (
		found  atomic.Bool
		result atomic.Value
		wg     sync.WaitGroup
	)

	for worker := 0; worker < workers; worker++ {
		start := len(dict) * worker / workers
		end := len(dict) * (worker + 1) / workers
		if start >= end {
			continue
		}
		wg.Add(1)
		go func(start, end int) {
			defer wg.Done()
			for i := start; i < end; i++ {
				if found.Load() {
					return
				}
				if target.testPassword(dict[i]) {
					if !found.Swap(true) {
						result.Store(append([]byte(nil), dict[i]...))
					}
					return
				}
			}
		}(start, end)
	}

	wg.Wait()
	if !found.Load() {
		return false, nil
	}
	return true, result.Load().([]byte)
}

func searchBruteForce(target *encryptedTarget, charset []byte, minLen, maxLen int, startingPassword []byte, workers int) (bool, []byte) {
	if len(charset) == 0 {
		return false, nil
	}

	indexMap := make(map[byte]int, len(charset))
	for i, b := range charset {
		indexMap[b] = i
	}

	var (
		found  atomic.Bool
		result atomic.Value
	)

	for length := minLen; length <= maxLen && !found.Load(); length++ {
		if len(startingPassword) > 0 && length < len(startingPassword) {
			continue
		}

		total, ok := powUint64(uint64(len(charset)), length)
		if !ok {
			total = math.MaxUint64
		}

		startIndex := uint64(0)
		if len(startingPassword) > 0 && length == len(startingPassword) {
			startIndex = passwordIndex(startingPassword, indexMap, len(charset))
		}
		if startIndex >= total {
			continue
		}

		remaining := total - startIndex
		if remaining == 0 {
			continue
		}

		var wg sync.WaitGroup
		for worker := 0; worker < workers; worker++ {
			begin := startIndex + remaining*uint64(worker)/uint64(workers)
			end := startIndex + remaining*uint64(worker+1)/uint64(workers)
			if begin >= end {
				continue
			}
			wg.Add(1)
			go func(length int, begin, end uint64) {
				defer wg.Done()
				digits := indexToDigits(begin, length, len(charset))
				candidate := digitsToPassword(digits, charset)
				for current := begin; current < end; current++ {
					if found.Load() {
						return
					}
					if target.testPassword(candidate) {
						if !found.Swap(true) {
							result.Store(append([]byte(nil), candidate...))
						}
						return
					}
					if current+1 >= end {
						return
					}
					incrementPassword(digits, candidate, charset)
				}
			}(length, begin, end)
		}
		wg.Wait()
	}

	if !found.Load() {
		return false, nil
	}
	return true, result.Load().([]byte)
}

func passwordIndex(password []byte, indexMap map[byte]int, base int) uint64 {
	var idx uint64
	for _, b := range password {
		idx = idx*uint64(base) + uint64(indexMap[b])
	}
	return idx
}

func indexToDigits(index uint64, length, base int) []int {
	digits := make([]int, length)
	for i := length - 1; i >= 0; i-- {
		digits[i] = int(index % uint64(base))
		index /= uint64(base)
	}
	return digits
}

func digitsToPassword(digits []int, charset []byte) []byte {
	password := make([]byte, len(digits))
	for i, digit := range digits {
		password[i] = charset[digit]
	}
	return password
}

func incrementPassword(digits []int, password, charset []byte) {
	for i := len(digits) - 1; i >= 0; i-- {
		digits[i]++
		if digits[i] < len(charset) {
			password[i] = charset[digits[i]]
			for j := i + 1; j < len(digits); j++ {
				digits[j] = 0
				password[j] = charset[0]
			}
			return
		}
		digits[i] = 0
		password[i] = charset[0]
	}
}

func powUint64(base uint64, exp int) (uint64, bool) {
	if exp == 0 {
		return 1, true
	}
	value := uint64(1)
	for i := 0; i < exp; i++ {
		if base != 0 && value > math.MaxUint64/base {
			return 0, false
		}
		value *= base
	}
	return value, true
}

func printTTYPrelude(target *encryptedTarget, runCfg runConfig) {
	writeStdout(fmt.Sprintf("Targeting file '%s' within the archive\n", target.name))
	switch target.encryption {
