func parseUintArg(value string) (uint64, string) {
	if value == "" {
		return 0, "cannot parse integer from empty string"
	}
	for i := 0; i < len(value); i++ {
		if value[i] < '0' || value[i] > '9' {
			return 0, "invalid digit found in string"
		}
	}
	n := new(big.Int)
	if _, ok := n.SetString(value, 10); !ok {
		return 0, "invalid digit found in string"
	}
	if n.BitLen() > 64 {
		return 0, "number too large to fit in target type"
	}
	return n.Uint64(), ""
}

func splitLongOption(arg string) (string, string, bool) {
	if idx := strings.IndexByte(arg, '='); idx >= 0 {
		return arg[:idx], arg[idx+1:], true
	}
	return arg, "", false
}

func longOptionValue(args []string, index *int, name, inlineValue string, hasInlineValue bool) (string, *cliError) {
	if hasInlineValue {
		return inlineValue, nil
	}
	if *index+1 >= len(args) {
		return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
	}
	next := args[*index+1]
	if strings.HasPrefix(next, "-") && next != "-" {
		if isKnownOptionToken(next) {
			return "", missingValueError(optionDisplays[canonicalNameForLong(name)])
		}
		return "", unexpectedArgumentError(next)
	}
	*index++
	return next, nil
}

func shortOptionValue(args []string, index *int, cluster string, clusterIndex *int, short byte) (string, *cliError) {
	if *clusterIndex+1 < len(cluster) {
		value := cluster[*clusterIndex+1:]
		*clusterIndex = len(cluster)
		return value, nil
	}
	if *index+1 >= len(args) {
		return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
	}
	next := args[*index+1]
	if strings.HasPrefix(next, "-") && next != "-" {
		if isKnownOptionToken(next) {
			return "", missingValueError(optionDisplays[canonicalNameForShort(short)])
		}
		return "", unexpectedArgumentError(next)
	}
	*index++
	*clusterIndex = len(cluster)
	return next, nil
}

func isKnownOptionToken(token string) bool {
	if token == "" {
		return false
	}
	if strings.HasPrefix(token, "--") {
		name, _, _ := splitLongOption(token)
		switch name {
		case "--inputFile", "--workers", "--passwordDictionary", "--charset", "--charsetFile", "--minPasswordLen", "--maxPasswordLen", "--fileNumber", "--startingPassword", "--help", "--version":
			return true
		default:
			return false
		}
	}
	if strings.HasPrefix(token, "-") && token != "-" {
		switch token[1] {
		case 'i', 'w', 'p', 'c', 's', 'h', 'V':
			return true
		default:
			return false
		}
	}
	return false
}

func markSeen(seen map[string]bool, order *[]string, canonical string) *cliError {
	if seen[canonical] {
		return duplicateArgumentError(optionDisplays[canonical])
	}
	seen[canonical] = true
	*order = append(*order, canonical)
	return nil
}

func canonicalNameForLong(name string) string {
	switch name {
	case "--inputFile":
		return "inputFile"
	case "--workers":
		return "workers"
	case "--passwordDictionary":
		return "passwordDictionary"
	case "--charset":
		return "charset"
	case "--charsetFile":
		return "charsetFile"
	case "--minPasswordLen":
		return "minPasswordLen"
	case "--maxPasswordLen":
		return "maxPasswordLen"
	case "--fileNumber":
		return "fileNumber"
	case "--startingPassword":
		return "startingPassword"
	default:
		return ""
	}
}

func canonicalNameForShort(short byte) string {
	switch short {
	case 'i':
		return "inputFile"
	case 'w':
		return "workers"
	case 'p':
		return "passwordDictionary"
	case 'c':
		return "charset"
	case 's':
		return "startingPassword"
	default:
		return ""
	}
}

func missingRequiredError(seenOrder []string) *cliError {
	usageParts := []string{"Usage: executable --inputFile <inputFile>"}
	for _, item := range seenOrder {
		if item == "inputFile" {
			continue
		}
		usageParts = append(usageParts, optionDisplays[item])
	}
	return &cliError{
		exitCode: 2,
		message: "error: the following required arguments were not provided:\n" +
			"  --inputFile <inputFile>\n\n" +
			strings.Join(usageParts, " ") + "\n\n" +
			"For more information, try '--help'.\n",
	}
}

func missingValueError(display string) *cliError {
	return &cliError{
		exitCode: 2,
		message: fmt.Sprintf(
			"error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n",
