func defaultWorkers() int {
	if cores := linuxPhysicalCores(); cores > 0 {
		return cores
	}
	cpus := runtime.NumCPU()
	if cpus <= 1 {
		return 1
	}
	return cpus / 2
}

func linuxPhysicalCores() int {
	if runtime.GOOS != "linux" {
		return 0
	}
	data, err := os.ReadFile("/proc/cpuinfo")
	if err != nil {
		return 0
	}

	entries := strings.Split(string(data), "\n\n")
	pairs := map[string]struct{}{}
	coreOnly := map[string]struct{}{}
	for _, entry := range entries {
		if strings.TrimSpace(entry) == "" {
			continue
		}
		var physicalID, coreID string
		lines := strings.Split(entry, "\n")
		for _, line := range lines {
			parts := strings.SplitN(line, ":", 2)
			if len(parts) != 2 {
				continue
			}
			key := strings.TrimSpace(parts[0])
			value := strings.TrimSpace(parts[1])
			switch key {
			case "physical id":
				physicalID = value
			case "core id":
				coreID = value
			}
		}
		if physicalID != "" && coreID != "" {
			pairs[physicalID+"/"+coreID] = struct{}{}
		} else if coreID != "" {
			coreOnly[coreID] = struct{}{}
		}
	}
	if len(pairs) > 0 {
		return len(pairs)
	}
	if len(coreOnly) > 0 {
		return len(coreOnly)
	}
	return 0
}

func formatDuration(d time.Duration) string {
	if d < 0 {
		d = 0
	}
	if d == 0 {
		return "0ns"
	}

	type unit struct {
		size time.Duration
		name string
	}
	units := []unit{
		{24 * time.Hour, "d"},
		{time.Hour, "h"},
		{time.Minute, "m"},
		{time.Second, "s"},
		{time.Millisecond, "ms"},
		{time.Microsecond, "us"},
		{time.Nanosecond, "ns"},
	}

	parts := make([]string, 0, 4)
	for _, unit := range units {
		if d < unit.size {
			continue
		}
		value := d / unit.size
		d -= value * unit.size
		parts = append(parts, strconv.FormatInt(int64(value), 10)+unit.name)
	}
	if len(parts) == 0 {
		return "0ns"
	}
	return strings.Join(parts, " ")
}

func pathExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func writeStdout(message string) {
	_, _ = os.Stdout.WriteString(message)
}

func writeStderr(message string) {
	_, _ = os.Stderr.WriteString(message)
}

func isTTY(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

