	}

	runCfg, err := validateRunConfig(cfg)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	target, err := loadEncryptedTarget(runCfg.cfg.inputFile, runCfg.cfg.fileNumber)
	if err != nil {
		writeStderr(err.message)
		os.Exit(err.exitCode)
	}

	tty := isTTY(os.Stdout)
	if tty {
		printTTYPrelude(target, runCfg)
	}

	start := time.Now()
	var found bool
	var password []byte
	if len(runCfg.dict) > 0 {
		found, password = searchDictionary(target, runCfg.dict, runCfg.cfg.workers)
	} else {
		found, password = searchBruteForce(
			target,
			runCfg.charset,
			runCfg.cfg.minPasswordLen,
			runCfg.cfg.maxPasswordLen,
			[]byte(runCfg.cfg.startingPassword),
			runCfg.cfg.workers,
		)
	}

	writeStdout("Time elapsed: " + formatDuration(time.Since(start)) + "\n")
	if found {
		writeStdout("Password found:" + string(password) + "\n")
		return
	}
	writeStdout("Password not found\n")
}

